import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Pb {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int length = Integer.parseInt(reader.readLine());
        String line = reader.readLine();
        ArrayList<String> wordsList = new ArrayList<>();
        int maxSequence = 0, currentSequence = 0;
        boolean inParentheses = false;
        String bufferWord = "";

        for (int i = 0; i < length; i++) {
            char c = line.charAt(i);
            if (c == '(') {
                if (currentSequence >= maxSequence) {
                    maxSequence = currentSequence;
                }
                currentSequence = 0;
                inParentheses = true;
                continue;
            }
            if (c == ')') {
                inParentheses = false;
                if (!bufferWord.isEmpty()) {
                    wordsList.add(bufferWord);
                    bufferWord = "";
                }
                continue;
            }
            if (inParentheses && c != '_') {
                bufferWord += c;
                continue;
            }
            if (inParentheses && c == '_' && !bufferWord.isEmpty()) {
                wordsList.add(bufferWord);
                bufferWord = "";
                continue;
            }
            if (!inParentheses && c != '_') {
                currentSequence++;
                if (i == length - 1 && currentSequence >= maxSequence) {
                    maxSequence = currentSequence;
                }
                continue;
            }
            if (!inParentheses && c == '_') {
                if (currentSequence >= maxSequence) {
                    maxSequence = currentSequence;
                }
                currentSequence = 0;
            }
        }
        System.out.println(maxSequence + " " + wordsList.size());
    }
}
